            { name: "筑基期", exp: 100, nextExp: 1000, maxMp: 200, maxSlots: 2 },
            { name: "金丹期", exp: 1000, nextExp: 10000, maxMp: 300, maxSlots: 3 },
            { name: "元婴期", exp: 10000, nextExp: 100000, maxMp: 400, maxSlots: 4 },
            { name: "化神期", exp: 100000, nextExp: 1000000, maxMp: 500, maxSlots: 5 },
            { name: "炼虚期", exp: 1000000, nextExp: 10000000, maxMp: 600, maxSlots: 6 },
            { name: "合体期", exp: 10000000, nextExp: 100000000, maxMp: 700, maxSlots: 7 },
            { name: "大乘期", exp: 100000000, nextExp: 1000000000, maxMp: 800, maxSlots: 8 },
            { name: "渡劫期", exp: 1000000000, nextExp: 10000000000, maxMp: 900, maxSlots: 9 }
        ];

        function calcCorrectStage(expValue) {
            let correctStage = STAGE_MAP[0];
            for (let i = 0; i < STAGE_MAP.length; i++) {
                if (expValue >= STAGE_MAP[i].exp) {
                    correctStage = STAGE_MAP[i];
                } else {
                    break;
                }
            }
            return correctStage;
        }

        function getSafeMessageId() {
            if (typeof window.parent.Mvu === 'undefined') return null;
            let msgId = null;
            if (window.parent.getCurrentMessageId) {
                msgId = window.parent.getCurrentMessageId();
            }
            if (msgId === null || msgId === undefined) {
                 if (window.parent.SillyTavern && window.parent.SillyTavern.getContext) {
                     const ctx = window.parent.SillyTavern.getContext();
                     if (ctx && ctx.chat && ctx.chat.length > 0) {
                         msgId = ctx.chat.length - 1;
                     }
                 }
            }
            return msgId;
        }

        async function syncCoreStats() {
            if(isSyncingStats) return;
            const p = window.parent;
            if(!p || !p.Mvu) return;

            const msgId = getSafeMessageId();
            if(msgId === null || msgId === undefined) return;

            const rawVars = p.Mvu.getMvuData({ type: 'message', message_id: msgId });
            if(!rawVars || !rawVars.stat_data || !rawVars.stat_data["世界与本源"]) return;

            const core = rawVars.stat_data["世界与本源"];
            const currentExp = Number(core["灵力值"] || 0);
            const currentStageName = core["境界"] || "练体期";
            const correctStageInfo = calcCorrectStage(currentExp);

            const bodies = rawVars.stat_data["夺舍女躯"] || {};
            // 这里去掉了原本强制本体+1的逻辑
            // 真实占用名额完全等于存活的女躯数量
            const actualSlots = Object.keys(bodies).length;

            const currentSlots = Number(core["已用夺舍名额"] || 0);
            let needSave = false;

            if(correctStageInfo.name !== currentStageName) {
                core["境界"] = correctStageInfo.name;
                needSave = true;
                toastr.success(`阳气满溢，灵台升华！神魂已自动突破至【${correctStageInfo.name}】！`);
            }

            if(actualSlots !== currentSlots) {
                core["已用夺舍名额"] = actualSlots;
                needSave = true;
            }

            if(needSave) {
                isSyncingStats = true;
                try {
                    await p.Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });
                    updateUI();
                } catch(e) {
                    console.error("核心数值自动同步失败", e);
                } finally {
                    isSyncingStats = false;
                }
            }
        }

        function getLatestData() {
            const msgId = getSafeMessageId();
            if(msgId === null || msgId === undefined) return _.get(getAllVariables(), 'stat_data', {});
            const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });
            return rawVars && rawVars.stat_data ? rawVars.stat_data : _.get(getAllVariables(), 'stat_data', {});
        }

        function updateUI() {
            const stat_data = getLatestData();
            const core = _.get(stat_data, '世界与本源', {});
            const bodies = _.get(stat_data, '夺舍女躯', {});
            const boys = _.get(stat_data, '男性鼎炉录', {});

            // 基础信息
            $('#ui-date').text(_.get(core, '日期', '未知'));
            $('#ui-week').text(_.get(core, '星期', '未知'));
            $('#ui-time').text(_.get(core, '时间', '未知'));
            $('#ui-world-intro').text(_.get(core, '世界简介', '暂无简介'));

            // 暴力采补模式状态更新
            const isBrutal = _.get(core, '暴力采补模式', false);
            if (isBrutal) {
                $('#ui-brutal-status').html('<span style="color:#ff4d4d; font-weight:bold;">[强行榨取]</span>');
            } else {
                $('#ui-brutal-status').html('<span style="color:#8892b0; font-weight:bold;">[常规采补]</span>');
            }

            const exp = Number(_.get(core, '灵力值', 0));
            const mp = Number(_.get(core, '法力值', 0));
            const stageInfo = calcCorrectStage(exp);
            $('#ui-stage').text(stageInfo.name);

            let expPct = Math.min((exp / stageInfo.nextExp) * 100, 100).toFixed(1);
            let mpPct = Math.min((mp / stageInfo.maxMp) * 100, 100).toFixed(1);

            $('#bar-lingli').css('width', expPct + '%');
            $('#text-lingli').text(`${exp} / ${stageInfo.nextExp}`);
            $('#bar-fali').css('width', mpPct + '%');
            $('#text-fali').text(`${mp} / ${stageInfo.maxMp}`);

            $('#ui-slots').text(_.get(core, '已用夺舍名额', 0));
            $('#ui-max-slots').text(stageInfo.maxSlots);

            const $selExec = $('#sel_executor');
            const curExec = $selExec.val();
            const $selBody = $('#sel-body');
            const curBody = $selBody.val();

            $selExec.empty();
            $selBody.empty().append('<option value="">-- 请选择神魂寄托之女躯 --</option>');

            const userName = "{{user}}";
            $selExec.append(`<option value="${userName}">${userName} (本体女躯)</option>`);

            const bodyKeys = Object.keys(bodies);
            if(bodyKeys.length > 0) {
                bodyKeys.forEach((name, index) => {
                    const isMain = (index === 0 || name === userName);
                    const prefix = isMain ? '【本体】' : '【分身】';
                    $selBody.append(`<option value="${name}">${prefix}${name}</option>`);
                    if(!isMain) {
                        $selExec.append(`<option value="${name}">${name} (分身女躯)</option>`);
                    }
                });
            } else {
                $selBody.append(`<option value="${userName}">【本体】${userName}</option>`);
            }

            if(curExec) $selExec.val(curExec);
            if(curBody) {
                $selBody.val(curBody);
            } else if (bodyKeys.length > 0) {
                $selBody.val(bodyKeys[0]);
            } else {
                $selBody.val(userName);
            }
            renderBodyDetail();

            const $selGirl = $('#sel-girl');
            const curGirl = $selGirl.val();
            $selGirl.empty().append('<option value="">-- 请选择受控男鼎 --</option>');
            Object.entries(boys).forEach(([name, data]) => {
                let qualityStr = _.get(data, '阳气鼎炉品阶') ? `(${_.get(data, '阳气鼎炉品阶')})` : '';
                $selGirl.append(`<option value="${name}">【男鼎】${name}${qualityStr}</option>`);
            });
            if(boys[curGirl]) $selGirl.val(curGirl);
            renderBoyDetail();
        }

        function renderBodyDetail() {
            const name = $('#sel-body').val();
            const stat_data = getLatestData();
            const bodies = _.get(stat_data, '夺舍女躯', {});
            const $container = $('#detail-body');

            let data = bodies[name];
            if(!data && name === "{{user}}") {
                data = { 红尘身份: "妖姬本体", 恩怨劣迹: "尚无记录", 位置: "未知" };
            }
            if(!data) {
                $container.hide();
                return;
            }

            $container.css('display', 'flex');

            let pList = _.get(data, '连带男伴', []);
            let pStr = (Array.isArray(pList) && pList.length > 0) ? pList.map(v => `<span style="color:#e0b0ff;">${v}</span>`).join('、') : '无';

            let isAuto = _.get(data, '是否自主运行', false);
            let autoStr = isAuto ? '<span style="color:#d45585;">是 (挂机引诱中)</span>' : '<span style="color:#a1c4e8;">否 (神魂操控中)</span>';
            let autoBtn = `<button class="action-small-btn toggle-auto-btn" data-name="${name}">切换</button>`;

            let isVirgin = _.get(data, '元阴状态') && _.get(data, '元阴状态').includes('是');
            let virginStr = isVirgin ? '<span style="color:#ff4d4d; border:1px solid #ff4d4d; padding:1px 4px; border-radius:2px; font-size:11px; margin-left:4px;">元阴未破</span>' : '';

            let featuresObj = _.get(data, '身体特写', {});
            let featuresHtml = '';
            if (Object.keys(featuresObj).length > 0) {
                Object.entries(featuresObj).forEach(([part, desc]) => {
                    featuresHtml += `<div class="feature-box"><span class="feature-tag">${part}</span> <span style="color:#e8d5b5;">${desc}</span></div>`;
                });
            } else {
                featuresHtml = '<span class="value" style="font-size:12px; color:#8892b0; font-style:italic;">暂无敏感部位被玩弄的记录...</span>';
            }

            let invObj = _.get(data, '物品栏', {});
            let invHtml = '<ul class="inv-list">';
            let hasItem = false;
            Object.entries(invObj).forEach(([itemName, itemData]) => {
                if(itemData.数量 > 0) {
                    hasItem = true;
                    invHtml += `
                        <li class="inv-item">
                            <div class="inv-info">
                                <div><span class="inv-name">${itemName}</span><span class="inv-count">x${itemData.数量}</span></div>
                                <div class="inv-desc">${itemData.描述 || '无描述'}</div>
                            </div>
                            <button class="btn-del-item" data-body="${name}" data-item="${itemName}">丢弃</button>
                        </li>
                    `;
                }
            });
            invHtml += '</ul>';
            if(!hasItem) invHtml = '<span style="color:#8892b0; font-style:italic; font-size:12px;">空无一物。</span>';

            let extraInfoObj = _.get(data, '额外信息', {});
            let extraInfoHtml = '';
            if (Object.keys(extraInfoObj).length > 0) {
                extraInfoHtml = '<div class="extra-info-list">';
                Object.entries(extraInfoObj).forEach(([k, v]) => {
                    extraInfoHtml += `<div class="extra-item"><span class="extra-key">${k}:</span> <span class="extra-val">${v}</span></div>`;
                });
                extraInfoHtml += '</div>';
            }

            $container.html(`
                <div class="detail-item"><span class="label">当前位置:</span> <span class="value">${_.get(data, '位置', '--')}</span></div>
                <div class="detail-item"><span class="label">当前衣着:</span> <span class="value" style="color:#f0a8c4;">${_.get(data, '衣着', '--')}</span></div>
                <div class="detail-item"><span class="label">红尘身份:</span> <span class="value">${_.get(data, '年龄', '--')} | ${_.get(data, '红尘身份', '--')}</span></div>
                <div class="detail-item"><span class="label">皮囊体态:</span> <span class="value">${_.get(data, '皮囊仙姿', '--')} | ${_.get(data, '娇躯体态', '--')}</span></div>
                <div class="detail-item"><span class="label">幽谷秘脔:</span> <span class="value">${_.get(data, '双峰形态', '--')} | ${_.get(data, '幽谷特征', '--')}${virginStr}</span></div>
                <div class="detail-item"><span class="label">宗族门楣:</span> <span class="value" style="font-size:12px;">${_.get(data, '宗族门楣', '无特殊记录')}</span></div>
                ${extraInfoHtml}
                <div class="detail-item"><span class="label">生前劣迹:</span> <span class="value" style="font-size:12px; color:#cfa8a8;">${_.get(data, '恩怨劣迹', '--')}</span></div>
                <div class="detail-item" style="align-items:center;"><span class="label">自主推演:</span> <span class="value">${autoStr}${autoBtn}</span></div>
                <div class="detail-item"><span class="label">男伴关系:</span> <span class="value">${pStr}</span></div>

                <div class="detail-item" style="flex-direction:column; margin-top:6px; border-top:1px dashed #4a191f; padding-top:6px;">
                    <span class="label">娇躯敏感特写:</span>
                    <div style="width:100%;">${featuresHtml}</div>
                </div>

                <div class="detail-item" style="flex-direction:column; margin-top:6px; border-top:1px dashed #4a191f; padding-top:6px;">
                    <span class="label">储物空间:</span>
                    <div style="width:100%;">${invHtml}</div>
                </div>
            `);
        }

        function renderBoyDetail() {
            const name = $('#sel-girl').val();
            const stat_data = getLatestData();
            const boys = _.get(stat_data, '男性鼎炉录', {});
            const $container = $('#detail-girl');

            if(!name || !boys[name]) {
                $container.hide();
                return;
            }

            const data = boys[name];
            $container.css('display', 'flex');

            let abnormalStr = _.get(data, '异常状态', '正常');
            let abBadge = abnormalStr !== '正常' ? `<span style="color:#e0b0ff; border:1px solid #e0b0ff; padding:1px 4px; border-radius:2px; font-size:11px; margin-left:4px;">${abnormalStr}</span>` : '';

            let thoughtHtml = '';
            if(unlockedThoughts.has(name)) {
                thoughtHtml = `
                    <span class="label" style="margin-bottom:4px;">此刻心思:</span>
                    <span class="value" style="font-size:12px; font-style:italic; background:rgba(42,15,18,0.5); padding:6px; border-radius:4px; border-left:2px solid #8b2331;">"${_.get(data, '当前想法', '精虫上脑，难以窥测...')}"</span>
                `;
            } else {
                thoughtHtml = `
                    <button class="thought-btn" data-name="${name}">消耗 10 法力窥探此男心声</button>
                `;
            }

            $container.html(`
                <div style="display:flex; justify-content:space-between; margin-bottom:4px; align-items:center;">
                    <span style="color:#d4af37; font-weight:bold; font-size:14px;">品阶：${_.get(data, '阳气鼎炉品阶', '未知')}${abBadge}</span>
                    <span style="color:#b59b9b; font-size:12px;">榨干：<span style="color:#e8d5b5; font-weight:bold;">${_.get(data, '采补记录', 0)}</span> 次</span>
                </div>
                <div class="detail-item"><span class="label">所在位置:</span> <span class="value" style="color:#a1c4e8;">${_.get(data, '位置', '--')}</span></div>
                <div class="detail-item"><span class="label">身份/性格:</span> <span class="value">${_.get(data, '年龄', '--')} | ${_.get(data, '世俗身份', '--')} | <span style="color:#dca5a5;">${_.get(data, '性情本心', '--')}</span></span></div>
                <div class="detail-item"><span class="label">隐秘性癖:</span> <span class="value" style="color:#ff9999;">${_.get(data, '隐秘性癖', '无')}</span></div>
                <div class="detail-item"><span class="label">因果态度:</span> <span class="value">${_.get(data, '与女性躯壳因果关系', '--')} | 态度:${_.get(data, '对躯壳态度', '--')}</span></div>
                <div class="detail-item"><span class="label">相貌体格:</span> <span class="value">${_.get(data, '皮相相貌', '--')} | ${_.get(data, '根骨体格', '--')}</span></div>
                <div class="detail-item"><span class="label">阳具形态:</span> <span class="value" style="font-size:12px;">${_.get(data, '肉茎形态','--')} | ${_.get(data, '阳具尺寸','--')}</span></div>
                <div class="detail-item"><span class="label">精关状态:</span> <span class="value" style="font-size:12px;">质量：${_.get(data, '精液质量','--')} | 精量：${_.get(data, '精液数量','--')}</span></div>
                <div class="detail-item"><span class="label">体质耐受:</span> <span class="value" style="color:#d45585;">${_.get(data, '体质耐受度', '--')}</span></div>

                <div class="detail-item" style="flex-direction:column; margin-top:6px; border-top:1px dashed #4a191f; padding-top:6px;">
                    ${thoughtHtml}
                </div>

                <div style="margin-top:12px; display:flex; justify-content:flex-end;">
                    <button class="btn-delete btn-del-boy" data-name="${name}">☠ 彻底抹除此鼎炉</button>
                </div>
            `);
        }

        async function init() {
            await waitGlobalInitialized('Mvu');
            updateUI();
            syncCoreStats();

            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
                updateUI();
                syncCoreStats();
            });

            $('.tab-btn').on('click', function() {
                const idx = $(this).data('tab');
                $('.tab-btn').removeClass('active');
                $(this).addClass('active');
                $('.tab-content').removeClass('active');
                $(`#tab${idx}`).addClass('active');
            });

            $('#sel-body').on('change', renderBodyDetail);
            $('#sel-girl').on('change', renderBoyDetail);

            $('.tag-btn').on('click', function() {
                const actionStr = $(this).data('action');
                let execName = $('#sel_executor').val() || '{{user}}';
                let finalText = execName + actionStr;
                try {
                    const p = window.parent;
                    if (p && p.$) {
                        const $textarea = p.$('#send_textarea');
                        if ($textarea.length) {
                            let currentVal = $textarea.val();
                            let newVal = currentVal.length > 0 ? currentVal + '\\n' + finalText : finalText;
                            $textarea.val(newVal).trigger('input');
                        }
                    }
                } catch (e) { console.error("输入交互失败:", e); }
            });

            // 暴力采补模式切换逻辑
            $(document).on('click', '#btn-toggle-brutal', async function() {
                const btn = $(this);
                if (btn.prop('disabled')) return;
                btn.text('切换中...').prop('disabled', true);

                try {
                    const msgId = getSafeMessageId();
                    if(msgId === null || msgId === undefined) throw new Error("无法获取当前楼层ID");
                    const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if(!rawVars || !rawVars.stat_data) throw new Error("无法获取变量数据");

                    let currentStatus = _.get(rawVars.stat_data, '世界与本源.暴力采补模式', false);
                    let newStatus = !currentStatus;
                    _.set(rawVars.stat_data, '世界与本源.暴力采补模式', newStatus);

                    await Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });

                    updateUI();

                    if (newStatus) {
                        toastr.success(`【暴力采补】已开启！男鼎将被疯狂榨干至死，灵力翻倍！`);
                    } else {
                        toastr.info(`已切回【常规采补】，细水长流不伤本源。`);
                    }
                } catch (e) {
                    console.error("暴力模式切换失败:", e);
                    toastr.error("模式切换失败，请检查运行环境");
                } finally {
                    btn.text('切换手段').prop('disabled', false);
                }
            });

            $(document).on('click', '.toggle-auto-btn', async function() {
                const btn = $(this);
                if (btn.prop('disabled')) return;
                const bodyName = btn.data('name');
                btn.text('切换中...').prop('disabled', true);

                try {
                    const msgId = getSafeMessageId();
                    if(msgId === null || msgId === undefined) throw new Error("无法获取当前楼层ID");
                    const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if(!rawVars || !rawVars.stat_data) throw new Error("无法获取变量数据");

                    if(!rawVars.stat_data["夺舍女躯"][bodyName]) {
                        toastr.warning("当前女躯暂无详细数据");
                        btn.text('切换').prop('disabled', false);
                        return;
                    }

                    let currentStatus = _.get(rawVars.stat_data, `夺舍女躯.${bodyName}.是否自主运行`, false);
                    let newStatus = !currentStatus;
                    _.set(rawVars.stat_data, `夺舍女躯.${bodyName}.是否自主运行`, newStatus);

                    await Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });
                    updateUI();

                    if (newStatus) {
                        toastr.success(`已开启【${bodyName}】的自主挂机！她将按原主人设自主行动。`);
                    } else {
                        toastr.info(`已夺回【${bodyName}】的绝对操控权！`);
                    }
                } catch (e) {
                    console.error("切换失败:", e);
                    toastr.error("状态切换失败");
                } finally {
                    btn.text('切换').prop('disabled', false);
                }
            });

            $(document).on('click', '.thought-btn', async function() {
                const btn = $(this);
                const boyName = btn.data('name');
                btn.text('施法中...').prop('disabled', true);

                try {
                    const msgId = getSafeMessageId();
                    if(msgId === null || msgId === undefined) throw new Error("无法获取当前楼层ID");
                    const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });

                    let fali = Number(_.get(rawVars.stat_data, '世界与本源.法力值', 0));
                    if (fali < 10) {
                        toastr.error("法力不足 10 点，无法施展窥心术！");
                        btn.text('消耗 10 法力窥探此男心声').prop('disabled', false);
                        return;
                    }

                    _.set(rawVars.stat_data, '世界与本源.法力值', fali - 10);
                    await Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });

                    unlockedThoughts.add(boyName);
                    updateUI();
                    toastr.success(`成功窥探男鼎【${boyName}】的心声`);
                } catch(e) {
                    console.error("窥心术施展失败:", e);
                    toastr.error("施展窥心术失败");
                    btn.text('消耗 10 法力窥探此男心声').prop('disabled', false);
                }
            });

            // 删除男鼎炉功能
            $(document).on('click', '.btn-del-boy', async function() {
                const btn = $(this);
                const boyName = btn.data('name');

                if(!confirm(`确定要将男鼎【${boyName}】从记录中彻底抹除吗？（删除后不可恢复）`)) {
                    return;
                }

                btn.text('抹除中...').prop('disabled', true);
                try {
                    const msgId = getSafeMessageId();
                    if(msgId === null || msgId === undefined) throw new Error("无法获取当前楼层ID");
                    const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });

                    if(rawVars && rawVars.stat_data && rawVars.stat_data["男性鼎炉录"] && rawVars.stat_data["男性鼎炉录"][boyName]) {
                        delete rawVars.stat_data["男性鼎炉录"][boyName];
                        await Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });
                        $('#sel-girl').val(''); // 清空当前选择
                        unlockedThoughts.delete(boyName);
                        updateUI();
                        toastr.success(`已将男鼎【${boyName}】彻底抹除`);
                    } else {
                        toastr.warning("未找到该男鼎的数据");
                        btn.text('☠ 彻底抹除此鼎炉').prop('disabled', false);
                    }
                } catch(e) {
                    console.error("删除失败:", e);
                    toastr.error("删除失败");
                    btn.text('☠ 彻底抹除此鼎炉').prop('disabled', false);
                }
            });

            // 丢弃物品功能
            $(document).on('click', '.btn-del-item', async function() {
                const btn = $(this);
                const bodyName = btn.data('body');
                const itemName = btn.data('item');

                btn.text('丢弃中...').prop('disabled', true);
                try {
                    const msgId = getSafeMessageId();
                    if(msgId === null || msgId === undefined) throw new Error("无法获取当前楼层ID");
                    const rawVars = Mvu.getMvuData({ type: 'message', message_id: msgId });

                    if(rawVars && rawVars.stat_data && rawVars.stat_data["夺舍女躯"][bodyName] && rawVars.stat_data["夺舍女躯"][bodyName]["物品栏"][itemName]) {
                        delete rawVars.stat_data["夺舍女躯"][bodyName]["物品栏"][itemName];
                        await Mvu.replaceMvuData(rawVars, { type: 'message', message_id: msgId });
                        updateUI();
                        toastr.success(`已从【${bodyName}】的身上丢弃了物品 [${itemName}]`);
                    } else {
                        toastr.warning("未找到该物品的数据");
                    }
                } catch(e) {
                    console.error("丢弃失败:", e);
                    toastr.error("丢弃失败");
                    btn.text('丢弃').prop('disabled', false);
                }
            });

            $('.btn-clone').on('click', async function() {
                const btn = $(this);
                const oldText = btn.text();
                const stat_data = getLatestData();
                const core = _.get(stat_data, '世界与本源', {});
                const currentExp = Number(_.get(core, '灵力值', 0));
                const stageInfo = calcCorrectStage(currentExp);
                const used = Number(_.get(core, '已用夺舍名额', 0));

                if (used >= stageInfo.maxSlots) {
                    btn.text("名额不足，请吸阳晋升！").css("color", "#ff4d4d");
                    setTimeout(() => { btn.text(oldText).css("color", "#d4af37"); }, 2000);
                    return;
                }

                btn.text("正在召唤法阵...");
                try {
                    await createChatMessages([{ role: 'system', message: '【clone_creation_panel】' }]);
                    btn.text("法阵已现！");
                    setTimeout(() => { btn.text(oldText); }, 2000);
                } catch(e) {
                    console.error(e);
                    btn.text("施法失败");
                    setTimeout(() => { btn.text(oldText); }, 2000);
                }
            });

            $('.btn-encounter').on('click', async function() {
                const btn = $(this);
                const oldText = btn.text();
                btn.text("正在寻找猎物...");
                try {
                    await createChatMessages([{ role: 'system', message: '【encounter_creation_panel】' }]);
                    btn.text("猎物出没！");
                    setTimeout(() => { btn.text(oldText); }, 2000);
                } catch(e) {
                    console.error(e);
                    btn.text("寻找失败");
                    setTimeout(() => { btn.text(oldText); }, 2000);
                }
            });
        }

        $(errorCatched(init));
    </script>
</body>
</html>
