import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界与本源: z.object({
    当前世界观: z.string().prefault('待初始化'),
    世界简介: z.string().describe('世界观简述与核心规则').prefault('暂无简介'),
    暴力采补模式: z.boolean().prefault(false),
    日期: z.string().prefault('待初始化'),
    时间: z.string().prefault('待初始化'),
    星期: z.string().prefault('待初始化'),
    境界: z.string().prefault('练体期'),
    灵力值: z.coerce.number().transform(v => Math.max(0, v)).prefault(0),
    法力值: z.coerce.number().transform(v => Math.max(0, v)).prefault(100),
    已用夺舍名额: z.coerce.number().transform(v => Math.max(0, v)).prefault(0)
  }),

  夺舍女躯: z.record(
    z.string().describe('躯壳姓名'),
    z.object({
      位置: z.string().prefault('未知'),
      年龄: z.string().prefault('未知'),
      红尘身份: z.string().prefault('未知'),
      皮囊仙姿: z.string().prefault('未知'),
      娇躯体态: z.string().prefault('未知'),
      双峰形态: z.string().prefault('未知'),
      幽谷特征: z.string().prefault('未知'),
      元阴状态: z.string().prefault('未知'),
      衣着: z.string().prefault('未知'),
      身体特写: z.record(
        z.string().describe('部位'),
        z.string().describe('特写描述')
      ).transform(data => {
        const entries = Object.entries(data);
        const sliced = entries.slice(-3);
        return Object.fromEntries(sliced);
      }).prefault({}),
      宗族门楣: z.string().prefault('未知'),
      恩怨劣迹: z.string().prefault('未知'),
      额外信息: z.record(z.string(), z.string()).prefault({}),
      连带男伴: z.array(z.string()).prefault([]),
      是否自主运行: z.boolean().prefault(false),
      物品栏: z.record(
        z.string().describe('物品名'),
        z.object({
          描述: z.string().prefault('无描述'),
          数量: z.coerce.number().transform(v => Math.max(0, v)).prefault(1)
        })
      ).transform(data => Object.fromEntries(Object.entries(data).filter(([_, item]) => item.数量 > 0))).prefault({})
    })
  ),

  男性鼎炉录: z.record(
    z.string().describe('男性姓名'),
    z.object({
      位置: z.string().prefault('未知'),
      年龄: z.string().prefault('未知'),
      世俗身份: z.string().prefault('未知'),
      性情本心: z.string().prefault('未知'),
      隐秘性癖: z.string().prefault('未知'),
      与女性躯壳因果关系: z.string().prefault('未知'),
      对躯壳态度: z.string().prefault('未知'),
      皮相相貌: z.string().prefault('未知'),
      根骨体格: z.string().prefault('未知'),
      阳气鼎炉品阶: z.string().prefault('未知'),
      阳具尺寸: z.string().prefault('未知'),
      肉茎形态: z.string().prefault('未知'),
      精液质量: z.string().prefault('未知'),
      精液数量: z.string().prefault('未知'),
      体质耐受度: z.string().prefault('未知'),
      异常状态: z.string().prefault('正常'),
      当前想法: z.string().prefault('未知'),
      采补记录: z.coerce.number().transform(v => Math.max(0, v)).prefault(0)
    })
  )
});

$(() => {
  registerMvuSchema(Schema);
})

